"""Prompt and sampling for calibrating the claim-audit judges on LLM-AggreFact.

The judges, decoding settings, label set, and decision rules are those of
run_llm_claim_audit.py; only the evidence changes from a user's interaction
history to a grounding document. SUPPORTED maps to the benchmark's
"supported" label and every other label to "unsupported".
"""

from __future__ import annotations

import numpy as np
import pandas as pd

SYSTEM_DOC = (
    "You are an expert annotator auditing claims generated by a language model. "
    "You will see a document and ONE claim that a model wrote. "
    "Judge only from the document shown; do not rely on outside knowledge."
)

INSTRUCTIONS_DOC = """Choose exactly one label for the claim:
- SUPPORTED: the document clearly supports the claim as stated.
- OVERGENERALIZED: the claim has some basis but states it more broadly or strongly than the document warrants.
- OVERLY_SPECIFIC: the general direction may be supported, but the claim adds details, qualifiers, motives, or circumstances that the document cannot show.
- NOT_SUPPORTED: nothing in the document supports the claim, and nothing contradicts it.
- CONTRADICTED: the document points against the claim.

Return JSON only: {"label": "<one label>", "reason": "<at most 25 words>"}"""


def doc_prompt(doc: str, claim: str) -> str:
    return f"Document:\n{doc}\n\nClaim: \"{claim}\"\n\n" + INSTRUCTIONS_DOC


def build_sample(df: pd.DataFrame, per_label: int, seed: int, max_doc_tokens: int) -> pd.DataFrame:
    """Draw up to per_label supported and per_label unsupported claims from every source dataset."""
    rng = np.random.default_rng(seed)
    df = df.assign(doc_tokens=df["doc"].str.len() / 4)
    df = df[df["doc_tokens"] <= max_doc_tokens]
    frames = []
    for name, part in df.groupby("dataset", sort=True):
        for label in (0, 1):
            pool = part[part["label"] == label]
            frames.append(pool.iloc[rng.permutation(len(pool))[:per_label]])
    sample = pd.concat(frames)
    sample = sample.assign(key=sample["dataset"] + ":" + sample.index.astype(str))
    return sample.iloc[rng.permutation(len(sample))].reset_index(drop=True)
